      "achados": [
        {
          "proposicao": "Um FPSO é definido como unidade flutuante de produção, armazenamento e transferência de petróleo, formada por subsistemas da planta de processamento primário destinados a separar óleo, gás e água e enquadrar essas fases para transferência ou descarte.",
          "trechos": [
            "Ea8bda43408ec1fdb:697:1391",
            "Ea8bda43408ec1fdb:1391:2091"
          ],
          "condicoes": [],
          "limites": [
            "É definição geral da unidade, não detalha sistemas de emergência de offloading"
          ]
        },
        {
          "proposicao": "O óleo enquadrado é transferido para terra por meio de navios tanques, conectando o processamento primário ao contexto operacional de offloading.",
          "trechos": [
            "Ea8bda43408ec1fdb:1391:2091"
          ],
          "condicoes": [
            "Após enquadramento do óleo nos requisitos para transferência"
          ],
          "limites": [
            "Não especifica arranjo de transferência, sequência operacional nem critérios de segurança"
          ]
        },
        {
          "proposicao": "Parte do gás produzido é queimada para manter a pressão do sistema em condição normal de operação ou em eventos de falha e/ou emergência, evidenciando interface entre contingências de processo e operação da unidade.",
          "trechos": [
            "Ea8bda43408ec1fdb:1391:2091",
            "Ea8bda43408ec1fdb:2091:2494"
          ],
          "condicoes": [
            "Condição normal de operação",
            "Eventos de falha e/ou emergência"
          ],
          "limites": [
            "O trecho não vincula diretamente essa prática ao ESD de offloading",
            "Não informa critérios de acionamento ou limites operacionais"
          ]
        }
      ]
    },
    {
      "id": "E6cdf85c6294e4a38",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "Nas análises numéricas da dissertação, foram considerados parâmetros de pior condição de operação aceitável para continuidade do offloading nas fases de aproximação, amarração e transferência de óleo, vinculados à geração de energia e propulsão do NADP.",
          "trechos": [
            "E6cdf85c6294e4a38:0:700"
          ],
          "condicoes": [
            "Análises numéricas de avaliação de downtime",
            "Continuidade das operações de offloading"
          ],
          "limites": [
            "Os valores dos parâmetros estão apagados e não podem ser reconstruídos",
            "Resultado aplicável ao estudo citado, não regra universal"
          ]
        },
        {
          "proposicao": "A dissertação também avaliou cenários mais restritivos com redução da potência disponível no navio aliviador, indicando uso de sensibilidade operacional para estimar downtime.",
          "trechos": [
            "E6cdf85c6294e4a38:700:1398"
          ],
          "condicoes": [
            "Avaliações numéricas complementares",
            "Uso de limite de demanda contínua de potência mais restritivo"
          ],
          "limites": [
            "Não há resultados quantitativos recuperáveis neste trecho",
            "Trata-se de metodologia e escopo do estudo, não recomendação normativa"
          ]
        },
        {
          "proposicao": "Uma proposta de setor operacional para NADP discutida em trabalho citado adota como premissas a não utilização do hawser para simplificar operações, maior distância entre unidade de produção e embarcação de alívio para reduzir exposição à colisão direta, e estratégia de posicionamento com dois pontos de pivotamento para evitar alinhamento longitudinal entre NADP e FPSO.",
          "trechos": [
            "E6cdf85c6294e4a38:1398:2097",
            "E6cdf85c6294e4a38:2097:2365"
          ],
          "condicoes": [
            "Proposta alternativa de setor operacional",
            "Diretriz de simplificação das operações mencionada para o Mar do Norte"
          ],
          "limites": [
            "É proposta discutida em referência citada, não requisito brasileiro",
            "A aplicabilidade depende do arranjo operacional e da estratégia de posicionamento considerada"
          ]
        }
      ]
    }
